/**
 * This file describes a generated template_contents/<uuid>.json file that is generated by an app-kit build server
 */

import type { ImageUrls, ImageLicence } from "../types/Image";
import type { TaxonType, TaxonWithImage } from "./BackboneTaxonomy";
import type { TemplateContentFeature, FeatureBase } from "../types/Features";

export type TemplateContentType = {
  title: string
  author: string
  lastModified: string
  publishedAt: string
  slug: string
  contents: Record<string, any>
}

export enum ComponentTypes {
  image = 'image',
  text = 'text',
  templateContentLink = 'templateContentLink',
}

export enum TemplateType {
  page = 'page',
  feature = 'feature',
}

export type ComponentContent = {
  type: ComponentTypes
  required?: boolean
  helpText?: string
}

export type TemplateContentComponent = {
  templateName: string
  type: string
  version: number
  idnetifierContent: string
  contents: Record<string, ComponentContent>
}

export type Page = TemplateContentType & {
  version: number
  templateFileName: string
  templateName: string
  templateUrl: string
  contents: Record<string, any>
  linkedTaxa: TaxonType[]
  linkedTaxonProfiles: TaxonWithImage[]
}

export type TemplateContentNavigationEntry = {
  url: string
  children: TemplateContentNavigationEntry[]
  linkName: string
  link_name: string /** should be deprecated in the future */
}

export type TemplateContentNavigation = TemplateContentNavigationEntry[]; 

export type LicencedTemplateContentImage = {
  image : {
    imageUrl: ImageUrls | null,
    licence: ImageLicence | {}
  }
}


export type TemplateContentSlugWithTaxa = {
  slug: string
  linkedTaxa: TaxonType[]
}

export type TemplateContentSlugsByTemplateName = {
  [templateName: string]: TemplateContentSlugWithTaxa[]
}


export class TemplateContent {

  language: string | null = null;
  
  constructor (private templateContentFeature: TemplateContentFeature) {
    this.templateContentFeature = templateContentFeature;
  }

  async load (language: string) {
    this.language = language;

  }

  async getTemplateContentSlugsByTemplateName(templateName: string, limit?: number | null, offset?: number | null): Promise<TemplateContentSlugWithTaxa[]> {

    let slugs: TemplateContentSlugWithTaxa[] = [];

    if (this.language && this.templateContentFeature.byTemplateName[this.language]) {
      const registryPath = this.templateContentFeature.byTemplateName[this.language];
      const response = await fetch(registryPath);
      if (response.ok) {
        const data = await response.json() as TemplateContentSlugsByTemplateName;
        if (data[templateName]) {
          slugs = data[templateName];
          if (limit !== undefined && limit !== null) {
            slugs = slugs.slice(offset || 0, (offset || 0) + limit);
          }
        }
      }
    }

    return slugs;
  }

  async getTaxonTemplateContentSlugsByTemplateName(templateName: string, taxon: TaxonType, limit?: number | null, offset?: number | null): Promise<TemplateContentSlugWithTaxa[]> {
    const candidates = await this.getTemplateContentSlugsByTemplateName(templateName);
    const filtered = candidates.filter(slug => slug.linkedTaxa.some(t => t.nameUuid === taxon.nameUuid));

    if (limit !== undefined && limit !== null) {
      return filtered.slice(offset || 0, (offset || 0) + limit);
    }

    return filtered;

  }


}